import {Injectable} from '@angular/core';
import {HttpBackend, HttpClient, HttpParams} from '@angular/common/http';
import {Observable, of} from 'rxjs';
import {environment} from "../../environments/environment";
import {map, shareReplay, tap} from "rxjs/operators";
import {
  CreateStokvelRequest,
  JoinRequestDTO,
  PaginatedResponse,
  RotationQueueDto,
  SavingsTermDto,
  StokvelMemberDto,
  StokvelResponse,
  StokvelTypeDto,
  normalizeStokvelMember
} from "../../models";
import {CacheService} from "../cache/cache.service";

@Injectable({
  providedIn: 'root'
})
export class StokvelService {

  private apiUrl = `${environment.apiUrl}stokvels`;
  private httpWithoutInterceptor: HttpClient;
  private cache = new Map<string, Observable<any>>();

  constructor(private http: HttpClient,
              private handler: HttpBackend,
              private cacheService: CacheService) {
    this.httpWithoutInterceptor = new HttpClient(handler);
  }

  getStokvelTypes(): Observable<StokvelTypeDto[]> {
    return this.http.get<StokvelTypeDto[]>(`${environment.apiUrl}public/stokvel-types`);
  }

  getSavingsTerms(): Observable<SavingsTermDto[]> {
    return this.http.get<SavingsTermDto[]>(`${environment.apiUrl}public/savings-terms`);
  }

  createStokvel(stokvelData: CreateStokvelRequest): Observable<StokvelResponse> {
    return this.http.post<StokvelResponse>(`${this.apiUrl}`, stokvelData).pipe(
      tap(() => {
        this.clearAllStokvelCache();
      })
    );
  }

  getUserStokvels(auth0Id: string): Observable<StokvelResponse[]> {
    const cacheKey = `user-stokvels-${auth0Id}`;

    const cached = this.cacheService.get<StokvelResponse[]>(cacheKey);
    if (cached) {
      return cached;
    }

    const request$ = this.http.get<PaginatedResponse<StokvelResponse>>(`${this.apiUrl}/my-stokvels`).pipe(
      map(response => response.content)
    );

    this.cacheService.set(cacheKey, request$, 2 * 60 * 1000); // 2 minutes TTL
    return request$;
  }

  // Get with forced refresh (bypass cache)
  getUserStokvelsForceRefresh(auth0Id: string): Observable<StokvelResponse[]> {
    const cacheKey = `user-stokvels-${auth0Id}`;
    this.cacheService.delete(cacheKey);
    return this.getUserStokvels(auth0Id);
  }

  // Get full paginated response with caching
  getUserStokvelsPaginated(auth0Id: string, page: number = 0, size: number = 10): Observable<PaginatedResponse<StokvelResponse>> {
    const cacheKey = `user-stokvels-paginated-${auth0Id}-${page}-${size}`;

    const cached = this.cacheService.get<PaginatedResponse<StokvelResponse>>(cacheKey);
    if (cached) {
      return cached;
    }

    const request$ = this.http.get<PaginatedResponse<StokvelResponse>>(
      `${this.apiUrl}/my-stokvels?page=${page}&size=${size}`
    );

    this.cacheService.set(cacheKey, request$, 2 * 60 * 1000);
    return request$;
  }

  // Clear cache when stokvel is created/updated
  clearUserStokvelsCache(auth0Id: string): void {
    const keysToDelete: string[] = [];

    this.cacheService['cache'].forEach((value, key) => {
      if (key.startsWith(`user-stokvels-${auth0Id}`)) {
        keysToDelete.push(key);
      }
    });

    keysToDelete.forEach(key => this.cacheService.delete(key));
  }

  clearAllStokvelCache(): void {
    const keysToDelete: string[] = [];

    this.cacheService['cache'].forEach((value, key) => {
      if (key.startsWith('user-stokvels-')) {
        keysToDelete.push(key);
      }
    });

    keysToDelete.forEach(key => this.cacheService.delete(key));
  }

  getPublicStokvels(page: number = 0, size: number = 10): Observable<PaginatedResponse<StokvelResponse>> {
    const params = new HttpParams()
      .set('page', page.toString())
      .set('size', size.toString());

    // Uses PublicController endpoint (/api/public/) which requires no authentication
    return this.httpWithoutInterceptor.get<PaginatedResponse<StokvelResponse>>(
      `${environment.apiUrl}public/get-public-stokvels`, { params }
    );
  }

  joinStokvel(payload: JoinRequestDTO): Observable<JoinRequestDTO> {
    return this.http.post<JoinRequestDTO>(`${this.apiUrl}/join-request`, payload);
  }

  getStokvelById(id: number): Observable<StokvelResponse> {
    return this.http.get<StokvelResponse>(`${this.apiUrl}/${id}`).pipe(
      map(s => this.normalizeStokvelResponse(s))
    );
  }

  /** Fetches a PUBLIC stokvel detail without requiring authentication */
  getPublicStokvelById(id: number): Observable<StokvelResponse> {
    return this.httpWithoutInterceptor.get<StokvelResponse>(
      `${environment.apiUrl}public/stokvels/${id}`
    ).pipe(map(s => this.normalizeStokvelResponse(s)));
  }

  private normalizeStokvelResponse(s: StokvelResponse): StokvelResponse {
    if (!s) return s;
    const norm = (arr: any[] | undefined) => (arr ?? []).map(normalizeStokvelMember);
    return {
      ...s,
      members:        norm(s.members),
      adminMembers:   norm(s.adminMembers),
      regularMembers: norm(s.regularMembers),
    };
  }

  /** Returns IDs of stokvels the current user is a member of (any role) */
  getJoinedStokvelIds(): Observable<number[]> {
    return this.http.get<StokvelResponse[]>(`${this.apiUrl}/joined`).pipe(
      map(stokvels => stokvels.map(s => s.id))
    );
  }

  getJoinedStokvels(): Observable<StokvelResponse[]> {
    return this.http.get<StokvelResponse[]>(`${this.apiUrl}/joined`);
  }

  getPendingJoinRequests(stokvelId: number): Observable<any[]> {
    return this.http.get<any[]>(`${this.apiUrl}/${stokvelId}/join-requests/pending`);
  }

  updateJoinRequestStatus(requestId: number, status: string, adminNotes?: string): Observable<any> {
    return this.http.put(`${this.apiUrl}/join-requests/${requestId}/status`, { status, adminNotes });
  }

  removeMember(stokvelId: number, memberId: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${stokvelId}/members/${memberId}`);
  }

  // ── Admin Removal Proposals ──────────────────────────────────────────────
  proposeAdminRemoval(stokvelId: number, targetMemberId: number, reason: string): Observable<any> {
    return this.http.post(`${this.apiUrl}/${stokvelId}/removal-proposals`, { targetMemberId, reason });
  }

  getPendingRemovalProposals(stokvelId: number): Observable<any[]> {
    return this.http.get<any[]>(`${this.apiUrl}/${stokvelId}/removal-proposals/pending`);
  }

  approveRemovalProposal(stokvelId: number, proposalId: number, notes: string): Observable<any> {
    return this.http.put(`${this.apiUrl}/${stokvelId}/removal-proposals/${proposalId}/approve`, { notes });
  }

  rejectRemovalProposal(stokvelId: number, proposalId: number, notes: string): Observable<any> {
    return this.http.put(`${this.apiUrl}/${stokvelId}/removal-proposals/${proposalId}/reject`, { notes });
  }

  cancelRemovalProposal(stokvelId: number, proposalId: number): Observable<any> {
    return this.http.delete(`${this.apiUrl}/${stokvelId}/removal-proposals/${proposalId}`);
  }

  leaveStokvel(stokvelId: number): Observable<void> {
    return this.http.post<void>(`${this.apiUrl}/${stokvelId}/leave`, {});
  }

  getAdminStokvelIds(): Observable<number[]> {
    return this.http.get<number[]>(`${this.apiUrl}/admin/stokvel-ids`);
  }

  // ── Member management ────────────────────────────────────────────────────

  /** Get all members (admins + regulars) for a stokvel */
  getStokvelMembers(stokvelId: number): Observable<StokvelMemberDto[]> {
    return this.http.get<any[]>(`${this.apiUrl}/${stokvelId}/members`).pipe(
      map(list => (list ?? []).map(normalizeStokvelMember))
    );
  }

  /** Get only admin members for a stokvel */
  getStokvelAdmins(stokvelId: number): Observable<StokvelMemberDto[]> {
    return this.http.get<any[]>(`${this.apiUrl}/${stokvelId}/admins`).pipe(
      map(list => (list ?? []).map(normalizeStokvelMember))
    );
  }

  /** Add a member to a stokvel by email (admin only) */
  addMemberByEmail(stokvelId: number, userEmail: string, role: string = 'MEMBER'): Observable<StokvelResponse> {
    const params = new HttpParams().set('userEmail', userEmail).set('role', role);
    return this.http.post<StokvelResponse>(`${this.apiUrl}/${stokvelId}/members`, null, { params });
  }

  /** Update a member's role within a stokvel (admin only) */
  updateMemberRole(stokvelId: number, memberId: number, newRole: string): Observable<any> {
    return this.http.put(`${this.apiUrl}/${stokvelId}/members/${memberId}/role`, { newRole });
  }

  /** Get members with outstanding contributions for a stokvel (admin only) */
  getOutstandingMembers(stokvelId: number): Observable<any[]> {
    return this.http.get<any[]>(`${this.apiUrl}/${stokvelId}/members/outstanding`);
  }

  /** Send payment reminder emails to members with outstanding contributions (admin only) */
  requestPayment(stokvelId: number, amount?: number): Observable<{ message: string; remindersCount: number }> {
    const body = amount != null ? { amount } : {};
    return this.http.post<{ message: string; remindersCount: number }>(`${this.apiUrl}/${stokvelId}/request-payment`, body);
  }

  /** Get the authenticated user's total contributions across all stokvels */
  getUserContributions(): Observable<number> {
    return this.http.get<number>(`${this.apiUrl}/user/contributions`);
  }

  /** Get the authenticated user's next payout info */
  getUserNextPayout(): Observable<{ amount: number; daysUntilPayout: number }> {
    return this.http.get<{ amount: number; daysUntilPayout: number }>(`${this.apiUrl}/user/next-payout`);
  }

  // Dashboard endpoints
  getDashboardSummary(): Observable<any> {
    return this.http.get<any>(`${environment.apiUrl}dashboard/summary`);
  }

  getRecentActivities(limit: number = 10): Observable<any[]> {
    const params = new HttpParams().set('limit', limit.toString());
    return this.http.get<any[]>(`${environment.apiUrl}dashboard/recent-activities`, { params });
  }

  getPortfolioDistribution(): Observable<any[]> {
    return this.http.get<any[]>(`${environment.apiUrl}dashboard/portfolio-distribution`);
  }

  getMyStokvelsDetailed(): Observable<StokvelResponse[]> {
    return this.http.get<StokvelResponse[]>(`${environment.apiUrl}dashboard/my-stokvels-detailed`);
  }

  // ── Rotation (ROTATIONAL stokvels) ───────────────────────────────────────

  /** Get the full payout-rotation queue for a rotational stokvel. */
  getRotationQueue(stokvelId: number): Observable<RotationQueueDto> {
    return this.http.get<RotationQueueDto>(`${this.apiUrl}/${stokvelId}/rotation`);
  }

  /** Admin: manually advance the rotation to the next slot. */
  advanceRotation(stokvelId: number): Observable<{ message: string; currentSlot: number; totalSlots: number }> {
    return this.http.post<{ message: string; currentSlot: number; totalSlots: number }>(
      `${this.apiUrl}/${stokvelId}/rotation/advance`, {}
    );
  }

  /** Admin: re-shuffle and reset the entire rotation queue. */
  resetRotation(stokvelId: number): Observable<RotationQueueDto> {
    return this.http.post<RotationQueueDto>(`${this.apiUrl}/${stokvelId}/rotation/reset`, {});
  }

  /** Get the current authenticated user's position in the rotation queue. */
  getMyRotationPosition(stokvelId: number): Observable<{
    position: number;
    scheduledPayoutDate: string;
    payoutAmount: number;
    isCurrent: boolean;
    hasReceived: boolean;
    totalSlots: number;
  }> {
    return this.http.get<any>(`${this.apiUrl}/${stokvelId}/rotation/my-position`);
  }
}
